insert into ponew values
(1, 1, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Basiliximab is used in transplantation as:', '["Induction therapy to prevent early rejection", "A diuretic", "Treatment for kidney stones", "An antibiotic"]'::jsonb, 0, 'It blocks the IL-2 receptor.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 2, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'A contraindication to peritoneal dialysis is:', '["Wanting to work", "Being a child", "Extensive abdominal adhesions or an inability to do exchanges safely", "Living far from the hospital"]'::jsonb, 2, 'Assess suitability carefully.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 3, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Brain-dead organ donors need care to:', '["Stop all monitoring", "Lower the body temperature to 30 °C", "Withhold all fluids", "Maintain blood pressure, oxygenation and fluid balance"]'::jsonb, 3, 'Good donor care improves graft function.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 4, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Advance care planning for patients with ESKD means:', '["Deciding for the patient without asking", "Only discussing costs", "Stopping all treatment immediately", "Discussing their wishes about future treatment and end-of-life care"]'::jsonb, 3, 'It respects autonomy.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 5, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Encapsulating peritoneal sclerosis is a serious late complication of PD that causes:', '["Bowel obstruction from a thickened peritoneum", "Skin rash", "Hypertension only", "Kidney stones"]'::jsonb, 0, 'Risk rises with long PD duration.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 6, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Before a PD exchange, the most important step is:', '["Shaking the bag hard", "Removing the catheter cap with bare hands", "Warming the bag in a microwave", "Hand washing and wearing a mask, with strict aseptic technique"]'::jsonb, 3, 'Touch contamination causes peritonitis.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 7, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Leakage of PD fluid into the scrotum or labia suggests:', '["Normal PD", "A patent processus vaginalis or hernia", "Peritonitis", "Exit site infection"]'::jsonb, 1, 'Stop PD and investigate.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 8, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Fibrin in the PD effluent can block the catheter; it is managed by:', '["Removing the catheter immediately", "Adding heparin to the dialysate as prescribed", "Flushing with air", "Stopping all dialysis"]'::jsonb, 1, 'Fibrin is common during peritonitis.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 9, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Intraperitoneal antibiotics are the preferred route in PD peritonitis because they:', '["Do not need sterile technique", "Are cheaper than all tablets", "Give high local levels in the peritoneum", "Never cause side effects"]'::jsonb, 2, 'They can be added to the dialysis bags.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 10, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'A PD catheter exit site is cleaned:', '["Only once a month", "Daily or as instructed, with an antiseptic, and kept dry and secured", "With bare hands", "By pulling on the catheter"]'::jsonb, 1, 'Avoid pulling or twisting the catheter.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 11, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Acute rejection after kidney transplant is treated first with:', '["Stopping all immunosuppression", "Oral antibiotics", "High-dose IV steroids (pulse methylprednisolone)", "Dialysis only"]'::jsonb, 2, 'Biopsy confirms the diagnosis.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 12, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Cloudy PD effluent should first be:', '["Ignored if the patient feels well", "Used again for the next exchange", "Drained into the toilet and forgotten", "Sent for cell count, Gram stain and culture"]'::jsonb, 3, 'Start antibiotics as per protocol.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 13, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Transplant recipients on immunosuppression have higher long-term risk of:', '["Low cholesterol", "Kidney stones only", "Hypotension", "Skin cancer and lymphoma"]'::jsonb, 3, 'Advise sun protection and regular checks.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 14, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'PD dialysate should be warmed by:', '["A dry heat warmer or warming pad to body temperature", "A microwave oven", "Boiling water", "Leaving it in the sun"]'::jsonb, 0, 'Microwaves heat unevenly and can damage the bag.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 15, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'PD may be preferred to haemodialysis in:', '["Patients unable to keep clean technique at home", "Children and patients who want home-based independence", "Patients with recent abdominal surgery", "Patients with large abdominal hernias"]'::jsonb, 1, 'It preserves residual renal function longer.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 16, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'In CRRT, the replacement fluid is given to:', '["Clean the filter", "Lower blood pressure", "Increase urine output", "Replace the plasma water removed by convection"]'::jsonb, 3, 'It can be given pre- or post-filter.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 17, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'After transplant, a sudden fall in urine output with pain over the graft may be due to:', '["Low dietary salt", "Graft thrombosis, rejection or urine leak", "Overhydration", "Normal recovery"]'::jsonb, 1, 'Urgent ultrasound is needed.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 18, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Among renal transplant types, the best expected outcome is generally seen with:', '["Living-related donation", "Living non-related donation", "Cadaveric donation", "All types have identical outcomes"]'::jsonb, 0, 'A closer genetic match, as seen with living-related donors, is associated with the best transplant outcomes.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 19, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'In the first 24 hours after renal transplant, urine output of 600 mL/hour should be:', '["Restricted by stopping all IV fluids", "Replaced hour-by-hour with IV fluid", "Ignored, as it will settle by itself", "Treated with IV furosemide to promote diuresis"]'::jsonb, 1, 'The new graft may cause a large diuresis (post-transplant polyuria); replacement fluids are calculated each hour.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 20, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'A patient recovering from anaesthesia after a lung transplant requires particular nursing vigilance for:', '["Skin integrity exclusively", "Signs of rejection and pulmonary infection", "Bowel function exclusively", "Only cardiac monitoring, with no respiratory focus"]'::jsonb, 1, 'Post-transplant patients need close monitoring for graft rejection and infection, alongside standard post-anaesthetic respiratory and haemodynamic care.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 21, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'A bilirubin level above what value is used as a transplant criterion in FHF?', '[">50 micromol/L", ">300 micromol/L", ">1000 micromol/L", ">100 micromol/L"]'::jsonb, 1, 'A bilirubin this high reflects severe liver dysfunction and is one of the recognised criteria for considering urgent transplant.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 22, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'A common complication of Continuous Renal Replacement Therapy (CRRT) that requires close monitoring is:', '["Hyperglycaemia exclusively, with no other risk", "Electrolyte imbalance and circuit clotting", "Hypertension only", "Improved clotting with no bleeding risk"]'::jsonb, 1, 'CRRT carries risks of electrolyte disturbance from continuous filtration and circuit clotting (often requiring anticoagulation), both requiring vigilant monitoring.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 23, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Post-operative monitoring of cyclosporine levels in a renal transplant recipient is performed:', '["Once daily", "Every hour", "Only if symptoms develop", "Once weekly"]'::jsonb, 1, 'This unusually frequent monitoring reflects how tightly cyclosporine levels must be controlled to avoid both rejection and drug toxicity.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 24, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'At 10 years, survival on dialysis alone (without transplant) is approximately:', '["74.84%", "8.49%", "55.07%", "95%"]'::jsonb, 1, 'This strikingly low figure demonstrates why transplant, when possible, is so strongly preferred over long-term dialysis alone.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 25, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'In peritoneal dialysis, the dialysate is', '["Hyperosmosis", "Hyperosmolar", "Hyposmolar", "Normosmolar"]'::jsonb, 1, 'Peritoneal dialysate is hyperosmolar to draw fluid/waste out of the blood by osmosis.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 26, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'A renal transplant recipient on tacrolimus is at particular risk of:', '["Hypercoagulability from a strong immune system", "Increased antibody production and allergy", "Infection, nephrotoxicity and hyperglycaemia", "Weight loss and persistent hypotension"]'::jsonb, 2, 'Drug levels are monitored; interactions with antifungals and antibiotics are common.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 27, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Chronic transplant rejection typically develops over:', '["Months to years", "Minutes to hours", "Days to weeks", "1–4 days"]'::jsonb, 0, 'Chronic rejection is a slow, multifactorial process that unfolds over a much longer timeframe than the other rejection types.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 28, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'A major complication specific to peritoneal dialysis is:', '["Air embolism", "Dialysis disequilibrium syndrome exclusively", "Peritonitis", "Arteriovenous fistula thrombosis"]'::jsonb, 2, 'Peritonitis, introduced via the peritoneal catheter, is a major and common complication specific to peritoneal dialysis, presenting with cloudy effluent, abdominal pain, and fever.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 29, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'At 10 years, survival with a living-related renal transplant is approximately:', '["74.84%", "8.49%", "55.07%", "100%"]'::jsonb, 0, 'This figure dramatically outperforms both cadaveric transplant and dialysis-alone survival at the same time point.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 30, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'A patient on CRRT (dialysis) in ICU needs:', '["No nutrition at all until dialysis has stopped", "Potassium supplements added to every feed", "More protein, as amino acids are lost in the effluent", "Very low protein to reduce the urea production"]'::jsonb, 2, 'Protein needs may reach 1.5–2.5 g/kg/day.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 31, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Which of the following is an absolute contraindication to renal transplant?', '["Age over 60 with good health", "Well-controlled hypertension", "Active uncontrolled infection", "Mild anaemia"]'::jsonb, 2, 'An active, uncontrolled infection makes the immunosuppression required after transplant dangerously unsafe.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 32, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'The best timing for renal transplant relative to dialysis is:', '["Only after complete kidney failure with no urine output", "Pre-emptive (before dialysis) or with minimal dialysis time", "Only after years of dialysis", "Timing makes no difference to outcomes"]'::jsonb, 1, 'Transplanting before or very early in dialysis is associated with better outcomes than waiting through prolonged dialysis first.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 33, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Mrs Fatima, a post renal transplant patient in critical care unit is on continuous central venous pressure monitoring, as a critical care nurse this is only possible if she has which of the following in situ:', '["Arterial catheter", "Peripheral line", "Central venous catheter", "E.C.G."]'::jsonb, 2, 'Continuous CVP monitoring requires a central venous catheter in place.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 34, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Hyperacute transplant rejection occurs within:', '["Months to years", "Minutes to hours", "Days to weeks", "1–4 days"]'::jsonb, 1, 'This is the fastest and most immediate type of rejection, driven by pre-formed antibodies already present in the recipient.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 35, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'CRRT is preferred to intermittent haemodialysis in:', '["Haemodynamically unstable patients", "Stable outpatients", "Patients with no kidney disease", "Patients who can walk"]'::jsonb, 0, 'Slow continuous removal avoids hypotension.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 36, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Citrate anticoagulation in CRRT requires monitoring of:', '["Ionised calcium in the patient and circuit", "The platelet count only, checked daily", "The blood glucose only, every 4 hours", "The urine sodium only, every 12 hours"]'::jsonb, 0, 'Calcium is replaced by infusion.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 37, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'After renal transplant, a sudden fall in urine output with graft tenderness and fever suggests:', '["Over-hydration from excess IV fluids", "A normal post-operative recovery pattern", "Acute rejection or graft vessel thrombosis", "Hypoglycaemia caused by the steroids"]'::jsonb, 2, 'Urgent ultrasound, Doppler and biopsy may be needed.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 38, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'A transplant recipient on immunosuppression develops a fever of 38.4 °C. The nurse should:', '["Stop all immunosuppressant drugs without waiting for orders", "Give paracetamol and review again at the next day''s ward round", "Assume it is a normal post-operative fever and observe only", "Treat as possible infection or rejection and inform the team at once"]'::jsonb, 3, 'Immunosuppressed patients may present atypically; cultures and early treatment are needed.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 39, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'During CRRT with regional citrate anticoagulation, the nurse must closely monitor:', '["Serum amylase and lipase every 6 hours", "Systemic and post-filter ionised calcium", "Serum troponin every hour", "Urine specific gravity every hour"]'::jsonb, 1, 'Citrate binds calcium. Citrate accumulation causes low ionised Ca²⁺ with a rising total/ionised calcium ratio.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 40, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'The Intensive care nursing intervention on renal recipient is aimed at measures to maintain fluid balance, kidney functions, prevention of infection and assessment for possible graft rejection and other complications.', '["Partially correct", "Absolutely correct", "Incorrect", "Not at all"]'::jsonb, 1, 'Fluid balance, kidney function, infection prevention, and rejection monitoring are indeed all core goals of post-transplant ICU nursing care.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 41, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A patient in PACU who received a large volume of irrigation fluid during TURP becomes confused with low sodium. This suggests:', '["Allergy to the urinary catheter", "Normal emergence from anaesthesia", "Hypercalcaemia from immobility after the operation", "TURP syndrome from fluid absorption"]'::jsonb, 3, 'Restrict fluids, check sodium and inform the team.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 42, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'The first drug for anaphylaxis with stridor and hypotension is:', '["IV chlorphenamine 10 mg slowly", "IV hydrocortisone 200 mg bolus", "IM adrenaline 0.5 mg (1:1000)", "Nebulised salbutamol 5 mg via mask"]'::jsonb, 2, 'Antihistamines and steroids are second-line. Repeat adrenaline after 5 minutes if needed.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 43, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Inadequate urine output (oligiuria) is defined as', '["Urine output of 0.5 ml/kg body weight/hour", "Urine output of less than 0.5 ml/kg body weight /hour", "Urine output of 5 ml/kg body weight /hour", "Urine output of more than 0.5 ml/kg body weight/ hour"]'::jsonb, 1, 'Oliguria in adults is generally defined as urine output less than 0.5 mL/kg/hour.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 44, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'You have a patient that might have a urinary tract infection (UTI). Which statement by the patient suggests that a UTI is likely?', '["“It burns when I pee.”", "“My pee smells sweet.”", "“I pee a lot.”", "“I go hours without the urge to pee.”"]'::jsonb, 0, 'Dysuria (burning on urination) is a classic UTI symptom.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 45, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'After TURP, continuous bladder irrigation is used to:', '["Provide nutrition through the bladder", "Cool the patient''s core temperature", "Prevent clots and catheter blockage", "Treat post-operative hypertension"]'::jsonb, 2, 'Output must exceed irrigation input. Fluid balance should subtract the irrigation volume.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 46, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Urethral catheterisation should not be attempted in pelvic trauma with:', '["Blood at the urethral meatus", "A normal hourly urine output", "Clear urine in the drainage bag", "An associated fractured wrist"]'::jsonb, 0, 'Blood at the meatus suggests urethral injury. A retrograde urethrogram is done first; suprapubic catheterisation may be needed.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 47, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'On the day of surgery, diuretics are generally:', '["Doubled in dose", "Continued as normal", "Given intravenously regardless of oral status", "Usually withheld"]'::jsonb, 3, 'Diuretics are typically held on the day of surgery to avoid compounding fluid shifts and electrolyte changes during the perioperative period.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 48, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A kidney transplant is usually placed in the:', '["Iliac fossa", "Upper abdomen near the stomach", "Original kidney position in the back", "Chest"]'::jsonb, 0, 'The vessels are joined to the iliac artery and vein.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 49, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A sudden rise in peak airway pressure with a ventilated patient should immediately prompt the nurse to check for:', '["Low fluid intake", "A blocked or kinked endotracheal tube, or bronchospasm/secretions", "The patient''s temperature only", "The IV infusion rate"]'::jsonb, 0, 'A sudden peak pressure rise suggests an airway/circuit problem — blocked/kinked tube, bronchospasm, secretions, or pneumothorax — requiring prompt assessment.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 50, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'The osmolality of the renal interstitium increases from the cortex toward the tip of the inner medulla, reaching approximately what value in a maximally concentrating human kidney?', '["About 300 mOsm/kg", "About 600 mOsm/kg at the papilla", "About 1200 mOsm/kg", "About 2500 mOsm/kg"]'::jsonb, 2, 'The interstitial osmolality rises from about 300 mOsm/kg in the cortex to as high as roughly 1200 mOsm/kg at the papillary tip of the inner medulla.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 51, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A diabetic patient on iv normal saline was discovered to have random blood sugar RBS of 2.5mmol/l, which of this action will you take as critical care Nurse?', '["Stop the fluid and wait for the Physician", "Send for the physician and wait for his order", "Change the fluid to glucose containing fluid", "Change to ringers'' lactate"]'::jsonb, 2, 'A dangerously low RBS of 2.5mmol/L on normal saline needs correction with a glucose-containing fluid.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 52, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A patient with hypokalemia (K⁺ 2.8 mEq/L) is receiving IV potassium. Which nursing action is essential?', '["Monitor serum K⁺ every 2 hours", "Administer as an IV bolus", "Dilute in 50 mL D5W over 10 minutes", "Infuse at 20 mEq/hr via central line"]'::jsonb, 0, 'Frequent serum K⁺ monitoring prevents overcorrection and hyperkalemia. IV potassium must be diluted and infused slowly (max 10 mEq/hr peripherally).', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 53, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'The simple test used to help diagnose and monitor certain lung conditions by measuring how much air you can breathe out in one forced breath, it can also measure the volume of air inspired and expired by the lungs. The critical care nurse knows this test as:', '["Spiro-meter", "Rest ECG monitoring", "Spiro-metery", "Stress ECG monitoring"]'::jsonb, 2, 'Measuring forced exhaled air volume to assess lung function is spirometry.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 54, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'What two organs in the body serve as a compensatory function to maintain acid-base balance?', '["Heart and Liver", "Gallbladder and Appendix", "Lungs and Spleen", "Kidneys and Lungs"]'::jsonb, 3, 'The lungs (CO2) and kidneys (HCO3⁻, H⁺) compensate to keep the pH in balance.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 55, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Daily weight monitoring in a patient with renal or cardiac fluid balance concerns is valuable because:', '["It only reflects nutritional status", "It has no correlation with fluid status", "Rapid weight change closely reflects fluid gain or loss", "It replaces the need for intake/output charting entirely"]'::jsonb, 2, 'Short-term weight changes closely track fluid retention or loss (1kg approximates 1L of fluid), making daily weights a sensitive complement to intake/output charting.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 56, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A potassium chloride infusion of 40 mEq is ordered in 500 mL of NS to run over 4 hours via a peripheral line. What is the resulting rate of potassium delivery in mEq/hr, and is this within the generally accepted peripheral IV limit of 10 mEq/hr?', '["20 mEq/hr; exceeds the peripheral limit", "40 mEq/hr; grossly exceeds the peripheral limit", "5 mEq/hr; well within the peripheral limit", "10 mEq/hr; at the upper safe peripheral limit"]'::jsonb, 3, '40 mEq over 4 hours = 10 mEq/hr, which is at the commonly accepted maximum peripheral infusion limit and should be given on a monitored line with cardiac monitoring.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 57, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Before thyroidectomy, potassium iodide is given for about:', '["2 months", "6 weeks", "2 weeks", "24 hours"]'::jsonb, 2, 'Potassium iodide (Lugol''s) is typically given for about 2 weeks before surgery.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 58, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Xanthochromia (yellow discoloration) of the cerebrospinal fluid on lumbar puncture is most suggestive of which condition?', '["Subarachnoid hemorrhage", "Guillain-Barre syndrome", "Normal CSF findings", "Bacterial meningitis only"]'::jsonb, 0, 'Xanthochromia results from the breakdown of red blood cells in the CSF and is a key finding supporting subarachnoid hemorrhage, especially when CT is negative but suspicion remains high.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 59, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Approximately one third of the body water exists in the: _______________________', '["Blood", "Extracellular fluid compartment", "Kidneys and Urinary bladder", "Transcellular fluid compartment"]'::jsonb, 1, 'About two-thirds of body water is intracellular and one-third extracellular — the extracellular compartment holds roughly a third.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 60, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'The main goal of treatment for acute glomerulonephritis is to:', '["Maintain fluid balance", "Encourage activity", "Teach intermittent catheterisation", "Encourage a high-protein intake"]'::jsonb, 0, 'Acute glomerulonephritis care centres on fluid balance: monitor weights, restrict fluid and sodium, and control BP and oedema.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 61, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A key preventive measure against contrast-induced nephropathy in at-risk patients is:', '["Adequate periprocedural IV hydration", "Withholding all medications", "Administering high-dose NSAIDs beforehand", "Fluid restriction before the procedure"]'::jsonb, 0, 'Adequate IV hydration before and after contrast administration is a primary strategy to reduce the risk of contrast-induced nephropathy in at-risk patients.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 62, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'According to the Parkland formula, how much fluid is a nurse required to administer to a patient weighing 70 kg with 30% total body surface area (TBSA) burns in the first 8 hours?', '["4200 mL", "2100 mL", "8400 mL", "2800 mL"]'::jsonb, 0, 'The Parkland formula is 4 mL x kg x %TBSA. For this patient, the total fluid needed in 24 hours is 4 × 70 × 30 = 8400 mL. Half of this amount, 4200 mL, is administered in the first 8 hours.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 63, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A chest drain should not be clamped during transport because:', '["The drain is more likely to fall out", "It increases the risk of infection", "A tension pneumothorax may develop", "The fluid inside the tube will clot"]'::jsonb, 2, 'Keep the bottle below chest level instead.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 64, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A forgotten ureteric stent left for many months can cause:', '["Bladder cure and better kidney function", "No problems at all", "Encrustation, infection and obstruction", "Better kidney function"]'::jsonb, 2, 'Use a stent register to track removal dates.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 65, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A PACU nurse receives a patient after spinal anaesthesia for knee surgery. Monitoring should include:', '["Only the wound site and dressing", "Only the respiratory rate each hour", "BP, block regression and urine output", "Only the patient''s appetite and thirst"]'::jsonb, 2, 'Urinary retention is common after spinal anaesthesia.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 66, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Standard preoperative fasting guidance for clear fluids before elective surgery is:', '["2 hours", "12 hours", "No restriction needed", "6 hours"]'::jsonb, 0, 'Clear fluids may be taken up to 2 hours before elective surgery under modern fasting guidelines, reducing unnecessary dehydration without increasing aspiration risk.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 67, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'During a routine respiratory assessment of a mechanically ventilated patient, the nurse notes new asymmetric chest expansion and absent breath sounds on the right, with tracheal deviation to the left. This most urgently suggests:', '["Mucus plugging of the left mainstem bronchus", "Right-sided tension pneumothorax", "A normal variant", "Right mainstem intubation"]'::jsonb, 1, 'Absent breath sounds with tracheal deviation away from the affected side and asymmetric chest expansion are classic signs of tension pneumothorax, a life-threatening emergency.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 68, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Minimum monitoring during general anaesthesia includes ECG, NIBP, pulse oximetry and:', '["Capnography and anaesthetic gas analysis", "Urine output and core temperature in every case", "Arterial line in every case", "Central venous pressure in every case"]'::jsonb, 0, 'A trained anaesthetist must be present throughout.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 69, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Which of the following decreases EEG activity during anaesthesia?', '["Early hypoxia", "Nitrous oxide", "Hypothermia", "Ketamine"]'::jsonb, 2, 'Hypothermia slows cerebral metabolism and reduces EEG activity. Ketamine, N2O and early hypoxia tend to increase or activate it.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 70, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Urinary diversion by ileal conduit means:', '["Ureters drain into an ileal segment brought out as a stoma", "Urine drains normally through the urethra after bladder removal", "A catheter is left permanently in the urethra after cystectomy", "The bladder is reconstructed using a segment of the colon"]'::jsonb, 0, 'Mucus in urine is normal. The stoma should be pink and moist; urine output is monitored.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 71, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'An epidural test dose (e.g. lidocaine with adrenaline) is given to detect:', '["The patient''s pain threshold", "Intravascular or intrathecal catheter placement", "Correct catheter length inside the epidural space", "Allergy to chlorhexidine"]'::jsonb, 1, 'Tachycardia suggests intravascular; rapid dense block suggests intrathecal.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 72, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'After hypospadias repair, the main nursing priority is:', '["Bathing in hot water immediately", "Protecting the urinary stent or catheter and the dressing", "Restricting all fluids to reduce urine output on the wound", "Encouraging the child to remove the catheter"]'::jsonb, 1, 'Keep the dressing clean and dry.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 73, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'The volume of air inspired or expired in a single breath during regular breathing is called:', '["Minute Volume", "Respiratory Volume", "Stroke Volume", "Tidal Volume"]'::jsonb, 3, 'The volume of a single normal breath is tidal volume.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 74, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A key electrolyte disturbance to monitor after giving salbutamol is:', '["Hypercalcaemia", "Hyponatraemia", "Hyperkalaemia", "Hypokalaemia"]'::jsonb, 3, 'Salbutamol pushes potassium into cells, which can lower blood potassium.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 75, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Volume of air during normal breath is;', '["Minute volume", "Inspiratory reserve volume", "Tidal volume", "Residual volume"]'::jsonb, 2, 'Normal single-breath volume is tidal volume.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 76, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Cystoscopy is usually performed with the patient in the:', '["Prone position with the legs apart", "Sitting position", "Lateral position", "Lithotomy position"]'::jsonb, 3, 'Protect the legs and nerves during positioning.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 77, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'A patient in the ICU develops signs of hypovolemic shock postoperatively. What interventions should the nurse prioritize?', '["Increasing IV fluid rate", "Monitoring vital signs closely", "Administering vasopressors", "Elevating the legs"]'::jsonb, 0, 'Increasing IV fluid administration restores circulating volume in hypovolaemic shock.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 78, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Haematuria with clots after a renal biopsy should be:', '["Treated by restricting fluids", "Reported, with close monitoring of pulse, BP and Hb", "Ignored as normal, as the patient will pass clots for a week", "Treated with heat packs"]'::jsonb, 1, 'Bed rest is usual for several hours after biopsy.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 79, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Obvious changes in the heart during myocardial infarction does not occur until', '["4hours", "6hours", "12hours", "48hours"]'::jsonb, 2, 'Obvious gross heart changes post-MI are typically not visible until about 12 hours after the event.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 80, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 421 · Medical-Surgical Nephrology II', 'Neuromuscular blocking agents used during mechanical ventilation contribute to ICU-AW risk by:', '["Having no lasting effect", "Only affecting the heart", "Strengthening muscles", "Prolonging weakness"]'::jsonb, 3, 'These drugs paralyse muscles for ventilator management, and their use is linked to prolonged weakness afterward.', 'NNP 421 · Medical-Surgical Nephrology II'),
(1, 81, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Skin-lightening creams containing mercury can cause:', '["Kidney damage (nephrotic syndrome)", "Polycystic kidneys", "Kidney stones", "Diabetes"]'::jsonb, 0, 'Public education reduces their use.', 'NNP 426 · Preventive Nephrology'),
(1, 82, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Preventing malaria and treating it promptly helps avoid:', '["Kidney stones", "Prostate enlargement", "Polycystic kidneys", "Acute kidney injury from severe malaria"]'::jsonb, 3, 'Blackwater fever causes AKI.', 'NNP 426 · Preventive Nephrology'),
(1, 83, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Albuminuria category A3 means a urine albumin-creatinine ratio above:', '["1 mg/mmol", "0.3 mg/mmol", "3 mg/mmol", "30 mg/mmol (300 mg/g)"]'::jsonb, 3, 'A3 shows severely increased albuminuria.', 'NNP 426 · Preventive Nephrology'),
(1, 84, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Children with recurrent urinary tract infections should be investigated to prevent:', '["Kidney stones only", "Diabetes", "Hypertension in parents", "Kidney scarring from reflux"]'::jsonb, 3, 'Ultrasound and other tests may be done.', 'NNP 426 · Preventive Nephrology'),
(1, 85, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Early referral to a nephrologist is recommended when eGFR falls below about:', '["Never needed", "90 mL/min/1.73 m² in all", "120 mL/min/1.73 m²", "30 mL/min/1.73 m² or there is rapid decline"]'::jsonb, 3, 'Early referral improves outcomes.', 'NNP 426 · Preventive Nephrology'),
(1, 86, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Health education for a newly diagnosed hypertensive patient to protect the kidneys includes:', '["Stopping drugs when BP is normal", "Avoiding clinic visits", "Taking medicines daily, checking BP and reducing salt", "Eating salty snacks"]'::jsonb, 2, 'Adherence prevents kidney damage.', 'NNP 426 · Preventive Nephrology'),
(1, 87, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'HIV-associated nephropathy is more common in:', '["People with well-controlled HIV only", "Children under 1 year only", "People of African descent with untreated HIV", "People with no HIV"]'::jsonb, 2, 'Antiretroviral therapy helps prevent it.', 'NNP 426 · Preventive Nephrology'),
(1, 88, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'The target blood pressure for most adults with CKD is generally below about:', '["160/100 mmHg", "180/110 mmHg", "100/60 mmHg in all", "130/80 mmHg (or as per local guideline)"]'::jsonb, 3, 'Good BP control slows progression.', 'NNP 426 · Preventive Nephrology'),
(1, 89, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Prompt treatment of diarrhoea and dehydration in children prevents:', '["Prerenal acute kidney injury", "Polycystic kidney disease", "Alport syndrome", "Wilms'' tumour"]'::jsonb, 0, 'Oral rehydration solution is the first step.', 'NNP 426 · Preventive Nephrology'),
(1, 90, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Using clean water and sanitation helps prevent kidney disease caused by:', '["Old age", "Polycystic kidney disease", "Genetic disorders", "Infections such as schistosomiasis and diarrhoeal illness"]'::jsonb, 3, 'Public health measures protect kidneys.', 'NNP 426 · Preventive Nephrology'),
(1, 91, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Untreated streptococcal throat and skin infections in children can lead to:', '["Polycystic kidney disease", "Wilms'' tumour", "Kidney stones", "Post-streptococcal glomerulonephritis"]'::jsonb, 3, 'Prompt antibiotic treatment helps prevent it.', 'NNP 426 · Preventive Nephrology'),
(1, 92, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Drinking adequate water helps prevent:', '["Hypertension in everyone", "Kidney stones and dehydration-related kidney injury", "Glomerulonephritis", "All types of CKD completely"]'::jsonb, 1, 'Advise more fluids in hot climates.', 'NNP 426 · Preventive Nephrology'),
(1, 93, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'A urine dipstick for protein in a community screening programme helps to:', '["Detect early kidney damage", "Measure blood sugar", "Diagnose malaria", "Check blood group"]'::jsonb, 0, 'Follow up positives with ACR and eGFR.', 'NNP 426 · Preventive Nephrology'),
(1, 94, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Smoking harms the kidneys mainly by:', '["Preventing infections", "Increasing urine output", "Damaging blood vessels and speeding up CKD progression", "Lowering blood pressure"]'::jsonb, 2, 'Stopping smoking slows decline.', 'NNP 426 · Preventive Nephrology'),
(1, 95, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Prevention of kidney stones includes:', '["Restricting all fluids", "High-salt diet", "Avoiding all calcium completely", "Plenty of fluids, less salt and less animal protein"]'::jsonb, 3, 'Dietary calcium should not be cut too low.', 'NNP 426 · Preventive Nephrology'),
(1, 96, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Pre-eclampsia screening in antenatal care protects the kidneys by:', '["Curing diabetes", "Preventing all kidney stones", "Increasing fluid intake", "Detecting high BP and proteinuria early"]'::jsonb, 3, 'Severe pre-eclampsia can cause AKI.', 'NNP 426 · Preventive Nephrology'),
(1, 97, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Community health workers can support kidney health by:', '["Performing transplants", "Screening BP and urine, and referring people at risk", "Prescribing dialysis", "Stopping all medicines"]'::jsonb, 1, 'Task-sharing extends reach.', 'NNP 426 · Preventive Nephrology'),
(1, 98, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Avoiding over-the-counter NSAID overuse protects the kidneys because NSAIDs:', '["Cure hypertension", "Reduce renal blood flow and can cause AKI", "Lower potassium", "Increase urine output"]'::jsonb, 1, 'Paracetamol is safer for mild pain.', 'NNP 426 · Preventive Nephrology'),
(1, 99, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Health promotion messages on World Kidney Day often include:', '["Keep fit, control sugar and BP, eat healthily and check your kidneys", "Eat more salt", "Take painkillers daily", "Avoid all doctors"]'::jsonb, 0, 'The ''golden rules'' of kidney health.', 'NNP 426 · Preventive Nephrology'),
(1, 100, 'Nephrology Nursing Mock — Day 6 Morning (Nov 2026)', 'NNP 426 · Preventive Nephrology', 'Sickle cell disease can cause kidney damage, so prevention includes:', '["Avoiding all checks", "Fluid restriction", "Regular NSAID use", "Good hydration, regular reviews and early treatment of crises"]'::jsonb, 3, 'Monitor urine protein in older children.', 'NNP 426 · Preventive Nephrology'),
(2, 1, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'The first-line drug for preventing and treating postpartum haemorrhage is:', '["Salbutamol", "Ergometrine in pre-eclampsia", "Nifedipine", "Oxytocin"]'::jsonb, 3, 'Ergometrine is avoided in hypertension. Misoprostol, carboprost and tranexamic acid are other options.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 2, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'A patient in labour has premature rupture of membranes with meconium-stained liquor. This finding is significant because it may indicate:', '["A sign of maternal infection only", "A completely normal, reassuring finding with no significance", "Definite fetal death, requiring no further action", "Possible fetal distress, requiring closer fetal monitoring"]'::jsonb, 3, 'Meconium-stained liquor can indicate fetal distress and requires closer fetal monitoring and preparation for potential neonatal complications at delivery.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 3, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Which drug is contraindicated for controlling postpartum bleeding in a woman with eclampsia?', '["Carboprost", "Ergometrine", "Misoprostol", "Oxytocin"]'::jsonb, 1, 'Ergometrine causes vasoconstriction that can dangerously raise already-high blood pressure.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 4, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'When the mother sacrifice glucose for the foetal energy, the mother utilizes:', '["High density lipoproteins", "Triglycerides", "Glucose just as the fetus", "Cholesterol"]'::jsonb, 1, 'The correct answer is: Triglycerides.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 5, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'A classic triad of intussusception is:', '["Projectile vomiting, an olive mass and a metabolic alkalosis", "Fever, rash, conjunctivitis and peeling of the fingertips", "Colicky pain, sausage-shaped mass, redcurrant jelly stool", "Bilious vomiting, jaundice and pale, chalky stools"]'::jsonb, 2, 'Not all three are present in every child.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 6, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Common causes of antepartum haemorrhage from 24 weeks'' gestation include which of the following?', '["placenta praevia", "Placenta abruption", "Normal period", "Uterine rupture"]'::jsonb, 0, 'Placenta praevia is a leading recognised cause of antepartum haemorrhage from 24 weeks onward.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 7, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Retained products of conception after delivery cause:', '["Hyperemesis gravidarum", "Polyhydramnios in the next pregnancy", "Hypertension and seizures", "Secondary PPH and infection"]'::jsonb, 3, 'Evacuation under antibiotic cover is needed.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 8, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'A patient with postpartum haemorrhage has a soft, boggy uterus on palpation. The most likely cause, according to the ''4 Ts'' framework, is:', '["Tissue (retained placenta)", "Tone (uterine atony)", "Trauma", "Thrombin (coagulopathy)"]'::jsonb, 1, 'A soft, boggy (atonic) uterus is the classic finding of uterine atony (''Tone''), the most common cause of postpartum haemorrhage.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 9, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'A postpartum patient develops sudden hypotension, hypoxia, and disseminated intravascular coagulation shortly after a difficult delivery. This presentation should raise suspicion for:', '["Normal blood loss from delivery", "Amniotic fluid embolism", "Simple postpartum fatigue", "Mastitis"]'::jsonb, 1, 'The triad of hypotension, hypoxia, and DIC around the time of delivery is classic for amniotic fluid embolism, a rare but often fatal obstetric emergency.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 10, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Placenta praevia classically presents with:', '["Painful dark bleeding with a hard, tender uterus", "Sudden sharp abdominal pain without any bleeding", "Painless bright red bleeding in late pregnancy", "Bleeding that occurs only after the delivery"]'::jsonb, 2, 'Digital vaginal examination is avoided until praevia is excluded. Placental abruption is painful with a woody hard uterus.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 11, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'A pregnant patient presents with severe, constant abdominal pain, a tense/rigid uterus, and dark vaginal bleeding. This presentation is most concerning for:', '["Braxton Hicks contractions", "Placental abruption", "Placenta praevia", "Normal labour onset"]'::jsonb, 1, 'Painful bleeding with uterine rigidity/tenderness is characteristic of placental abruption, an obstetric emergency threatening both mother and fetus.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 12, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Evacuation of retained products of conception (ERPC) is indicated in:', '["Ectopic pregnancy", "Threatened miscarriage with closed os and live fetus", "Incomplete miscarriage with heavy bleeding", "Normal pregnancy"]'::jsonb, 2, 'Manual vacuum aspiration is commonly used in Nigeria and is safer than sharp curettage.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 13, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'The most common presentation of a pre-eclamptic patient is:', '["Dyspareunia", "No symptoms", "Abdominal pain", "Convulsions"]'::jsonb, 1, 'Most women with pre-eclampsia have no symptoms. It is found by routine BP and urine checks, which is why antenatal screening matters.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 14, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Breast abscess in a postnatal woman is managed by:', '["Observation without any treatment for a week", "Cold compresses only, without antibiotics", "Drainage, antibiotics and continued milk removal", "Stopping breastfeeding on both sides permanently"]'::jsonb, 2, 'Staphylococcus aureus is the usual cause.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 15, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'The decision to transfuse blood or blood component should be based on laboratory tests assessment as well as....', '["Patient record of admission", "Patient weight", "Clinical assessment", "The use of red cells in surgery"]'::jsonb, 2, 'Transfusion decisions should combine lab results with the patient''s overall clinical assessment, not labs alone.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 16, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Among the 4 Ts of PPH, ''Tissue'' refers to:', '["Retained placental tissue", "Genital tract lacerations", "Clotting factor deficiency", "Uterine muscle tone"]'::jsonb, 0, 'Retained fragments of placenta or membranes prevent the uterus from contracting down fully, causing ongoing bleeding.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 17, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Acute lymphoblastic leukaemia treatment in ICU may cause:', '["Immediate iron overload needing chelation", "Hypercoagulability with deep vein thrombosis", "Polycythaemia with hyperviscosity and stroke", "Neutropenic sepsis and tumour lysis syndrome"]'::jsonb, 3, 'Prophylactic allopurinol or rasburicase and hydration prevent TLS.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 18, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'An inevitable miscarriage is one in which:', '["Bleeding occurs but the os is closed and the fetus alive", "The fetus has died but no bleeding occurs", "All products have passed and bleeding has stopped", "Bleeding occurs and the cervical os is open"]'::jsonb, 3, 'A threatened miscarriage has a closed os.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 19, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'The commonest surgical procedure used to treat ruptured tubal pregnancy is', '["oophorectomy", "Total hysterectomy", "Salpingo-oophorectomy", "Salpingectomy"]'::jsonb, 3, 'Salpingectomy (removal of the affected tube) is the standard surgery for a ruptured tubal pregnancy.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 20, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Some physiological changes in pregnancy influence normal biochemical values while others may mimic symptoms of medical disease. These symptoms include:', '["Nausea, vomiting and loss of appetite", "Nausea and vomiting", "Nausea", "Nausea, vomiting and severe diarrheoa"]'::jsonb, 0, 'The correct answer is: Nausea, vomiting and loss of appetite.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 21, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Wertheim''s (radical) hysterectomy is performed for:', '["Uterine fibroids", "Uterovaginal prolapse in older women", "Early cervical cancer", "Ovarian cysts"]'::jsonb, 2, 'It removes the uterus, parametrium, upper vagina and pelvic nodes.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 22, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Cervical incompetence is when the cervical tissue is:', '["Fully closed", "Thickened by fibroids", "Firm and long", "Weak"]'::jsonb, 3, 'Cervical incompetence is weakness of the cervical tissue, leading to painless dilatation in the second trimester.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 23, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Laparoscopic salpingostomy for ectopic pregnancy differs from salpingectomy because it:', '["Removes the whole tube", "Removes the ovary on the same side as the ectopic", "Removes the pregnancy but keeps the tube", "Removes the uterus"]'::jsonb, 2, 'Follow-up hCG is needed to check for persistent trophoblast.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 24, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'A normal arterial PaCO₂ in late pregnancy is about:', '["5.3 kPa (40 mmHg), the same as non-pregnant women", "4 kPa (30 mmHg), due to increased minute ventilation", "8 kPa (60 mmHg), due to progesterone", "6.5 kPa (49 mmHg), due to splinting of the diaphragm"]'::jsonb, 1, 'A ''normal'' PaCO₂ of 5.3 kPa in pregnancy may signal respiratory failure.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 25, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Following a vaginal birth with a postpartum haemorrhage of 1500 mL, the woman''s urine output should be:', '["Ignored if she feels well", "Measured only by weighing pads", "Checked once the next day by weighing the pads", "Monitored hourly with a catheter"]'::jsonb, 3, 'Low urine output signals ongoing hypovolaemia.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 26, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'A category 1 caesarean section (immediate threat to life of mother or baby) should ideally deliver the baby within:', '["4 hours of the decision", "The next elective list, within 24 hours", "24 hours of the decision", "30 minutes of the decision"]'::jsonb, 3, 'Category 2 targets within 75 minutes.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 27, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'In bacterial meningitis, dexamethasone is given before or with the first antibiotic dose to reduce:', '["Hearing loss and neurological complications", "The total duration of the antibiotic course", "Fever only, with no effect on outcome", "The need for maintenance IV fluids"]'::jsonb, 0, 'It is most effective in Haemophilus influenzae and pneumococcal meningitis.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 28, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Before major gynaecological surgery, blood is grouped and saved or cross-matched because:', '["It replaces the consent form", "It reduces infection", "Pelvic surgery can cause heavy bleeding", "The patient will always need a transfusion"]'::jsonb, 2, 'Check Hb and correct anaemia before elective surgery.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 29, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Pelvic inflammatory disease complicated by a tubo-ovarian abscess not responding to antibiotics may need:', '["No treatment, as it always resolves on its own", "Cervical cerclage", "Surgical or radiological drainage", "Oral iron only"]'::jsonb, 2, 'Long-term effects include infertility and ectopic pregnancy.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 30, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 422 · Gynaecology and Obstetrics in Nephrology', 'Vaginal bleeding after 28 weeks of pregnancy which is sudden in onset, painless, causeless and recurrent is known as.', '["Abruption placentae", "Abortion", "Vasa praevia", "Placenta praevia"]'::jsonb, 3, 'Sudden, painless, recurrent bleeding after 28 weeks is the classic description of placenta praevia.', 'NNP 422 · Gynaecology and Obstetrics in Nephrology'),
(2, 31, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A newborn with HR 80, gasping breaths and floppy tone needs:', '["Bag-mask ventilation", "Adrenaline first", "Routine care with the mother", "Chest compressions immediately"]'::jsonb, 0, 'If HR remains below 60 after effective ventilation, start compressions.', 'NNP 423 · Paediatric Nephrology'),
(2, 32, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'The IV adrenaline dose in paediatric cardiac arrest is:', '["100 mcg/kg (1 mL/kg of 1:1000)", "1 mg/kg (10 mL/kg of 1:10,000)", "10 mcg/kg (0.1 mL/kg of 1:10,000)", "0.1 mcg/kg (0.001 mL/kg of 1:1000)"]'::jsonb, 2, 'Repeat every 3–5 minutes.', 'NNP 423 · Paediatric Nephrology'),
(2, 33, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'In a child under 1 year, the head represents about what percentage of total body surface area in burns?', '["18%", "9%", "4.5%", "1%"]'::jsonb, 0, 'Children''s heads are larger, and legs smaller, than adults''.', 'NNP 423 · Paediatric Nephrology'),
(2, 34, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'The respiratory rate considered fast breathing in a child aged 2–12 months is:', '["30 breaths/min or more", "80 breaths/min or more", "50 breaths/min or more", "20 breaths/min or more"]'::jsonb, 2, 'For 1–5 years: 40 or more; under 2 months: 60 or more.', 'NNP 423 · Paediatric Nephrology'),
(2, 35, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Circumcision should NOT be performed in a baby with hypospadias because:', '["It increases bleeding in all babies", "It causes a hydrocele and urinary tract infection", "It cures hypospadias", "The foreskin may be needed for the repair"]'::jsonb, 3, 'Refer to a paediatric urologist.', 'NNP 423 · Paediatric Nephrology'),
(2, 36, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'The circulating blood volume of a term neonate is about:', '["20 mL/kg", "40 mL/kg (half the adult volume)", "150 mL/kg", "80–90 mL/kg"]'::jsonb, 3, 'A small absolute blood loss is significant in babies.', 'NNP 423 · Paediatric Nephrology'),
(2, 37, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Leukaemia in children most commonly presents with:', '["Weight gain and generalised oedema", "Hypertension and persistent headaches", "Pallor, fever, bruising and bone pain", "Jaundice and generalised itching"]'::jsonb, 2, 'Acute lymphoblastic leukaemia is the commonest childhood cancer.', 'NNP 423 · Paediatric Nephrology'),
(2, 38, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A ''Gillick competent'' child is one who:', '["Has enough understanding to consent to their own treatment", "Has no parents or guardians to give consent on their behalf", "Cannot consent at all", "Is always over 18"]'::jsonb, 0, 'Competence depends on the child and the decision.', 'NNP 423 · Paediatric Nephrology'),
(2, 39, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A double-volume exchange transfusion in a neonate uses about:', '["300–350 mL/kg of blood", "80–90 mL/kg of blood", "40–60 mL/kg of blood", "160–180 mL/kg of blood"]'::jsonb, 3, 'Neonatal blood volume is 80–90 mL/kg; double volume replaces about 85% of the baby''s red cells.', 'NNP 423 · Paediatric Nephrology'),
(2, 40, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'The usual threshold for treating neonatal hypoglycaemia is blood glucose below:', '["2.6 mmol/L (about 45 mg/dL)", "1.0 mmol/L only if the baby has seizures", "8.0 mmol/L (about 145 mg/dL)", "5.5 mmol/L (about 100 mg/dL)"]'::jsonb, 0, 'Babies at risk include preterm, small or large babies and babies of diabetic mothers.', 'NNP 423 · Paediatric Nephrology'),
(2, 41, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'The usual IV fluid for neonates in the first 24 hours is:', '["5% albumin", "Hartmann''s solution with potassium", "10% dextrose", "0.9% sodium chloride"]'::jsonb, 2, 'Neonates need glucose (4–6 mg/kg/min). Sodium and potassium are usually added after 24–48 hours.', 'NNP 423 · Paediatric Nephrology'),
(2, 42, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A ''double bubble'' sign on newborn abdominal X-ray suggests:', '["Pyloric stenosis", "Gastroschisis", "Hirschsprung''s disease", "Duodenal atresia"]'::jsonb, 3, 'It is associated with Down syndrome. Management is nasogastric decompression, fluids and duodenoduodenostomy.', 'NNP 423 · Paediatric Nephrology'),
(2, 43, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'An inguinal hernia in a child is usually due to:', '["Heavy lifting", "A patent processus vaginalis", "Obesity", "Weak abdominal muscles from age"]'::jsonb, 1, 'Infant hernias are repaired promptly because of a high risk of incarceration.', 'NNP 423 · Paediatric Nephrology'),
(2, 44, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Before pyloromyotomy, the most important preparation is:', '["Giving IV sodium bicarbonate to correct the acid-base disturbance", "Taking the baby to theatre immediately on arrival in the ward", "Correcting dehydration and alkalosis with IV fluids and potassium", "Giving frequent small oral feeds to build up the baby''s strength"]'::jsonb, 2, 'It is not a surgical emergency but a medical one. Anaesthesia with uncorrected alkalosis risks post-operative apnoea.', 'NNP 423 · Paediatric Nephrology'),
(2, 45, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Sudden infant death syndrome is most common at age:', '["Newborn first week", "2–4 months", "1–2 years", "5–6 years"]'::jsonb, 1, 'Risk factors: prone sleeping, smoking, overheating, soft bedding.', 'NNP 423 · Paediatric Nephrology'),
(2, 46, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Placental abruption is separation of the placenta:', '["Before delivery of the baby", "Only during the third stage", "Never before labour", "After delivery of the baby"]'::jsonb, 0, 'Abruption is partial or complete separation of the placenta before delivery of the baby.', 'NNP 423 · Paediatric Nephrology'),
(2, 47, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Before surgery for Wilms'' tumour, the abdomen should NOT be:', '["Measured or examined gently by the surgeon", "Inspected", "Palpated repeatedly", "Documented"]'::jsonb, 2, 'Rough handling may rupture the tumour and spread it.', 'NNP 423 · Paediatric Nephrology'),
(2, 48, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Pale stools and dark urine with prolonged jaundice in a 4-week-old baby suggest:', '["Biliary atresia (obstructive jaundice)", "Normal physiological jaundice", "Hypothyroidism only, needing thyroid hormone", "Breast milk jaundice only"]'::jsonb, 0, 'Urgent referral is needed.', 'NNP 423 · Paediatric Nephrology'),
(2, 49, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Inflation breaths for a term newborn are given:', '["One sustained breath held for 10 seconds", "Five breaths, each held for 2–3 seconds", "Ten breaths at a rate of 60 per minute", "Two quick breaths, each lasting 1 second"]'::jsonb, 1, 'They open fluid-filled lungs; then ventilate at 30–60 breaths per minute.', 'NNP 423 · Paediatric Nephrology'),
(2, 50, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Neonatal hypoglycaemia is treated with an IV bolus of:', '["5 mL/kg of 25% dextrose", "1 mL/kg of 5% dextrose", "10 mL/kg of 50% dextrose", "2 mL/kg of 10% dextrose"]'::jsonb, 3, 'Higher concentrations are hypertonic and damage veins.', 'NNP 423 · Paediatric Nephrology'),
(2, 51, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Severe neonatal jaundice is primarily concerning because untreated high bilirubin levels can cause:', '["No lasting harm regardless of level", "Kernicterus (bilirubin-induced brain damage)", "Improved neurological development", "Only mild, temporary skin discolouration with no other risk"]'::jsonb, 1, 'Untreated severe hyperbilirubinaemia can cross the blood-brain barrier and cause kernicterus, a form of permanent brain damage — hence the urgency of treatment (phototherapy/exchange transfusion).', 'NNP 423 · Paediatric Nephrology'),
(2, 52, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'The following is true about renal replacement therapy in children', '["Feeling faint or dizzy is a symptom of dehydration in children on peritoneal dialysis", "Children should be weighed only before the beginning of any dialysis session", "The extracorporeal circuit in haemodialysis should contain at least 20% of the child''s blood volume", "A general dialysis prescription can work for all children"]'::jsonb, 0, 'The correct answer is: Feeling faint or dizzy is a symptom of dehydration in children on peritoneal dialysis.', 'NNP 423 · Paediatric Nephrology'),
(2, 53, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Corticosteroids are given to a mother whose delivery is planned before 37 weeks to:', '["Help the baby''s lungs mature", "Keep the mother calm", "Prepare the cervix for delivery", "Prevent maternal fits"]'::jsonb, 0, 'Antenatal corticosteroids (dexamethasone/betamethasone) before 34–37 weeks speed fetal lung maturation and reduce RDS.', 'NNP 423 · Paediatric Nephrology'),
(2, 54, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A testicular torsion in a child needs surgery ideally within:', '["6 hours of onset of pain", "48 hours", "1 month", "2 weeks of the onset of pain"]'::jsonb, 0, 'Delay leads to loss of the testis.', 'NNP 423 · Paediatric Nephrology'),
(2, 55, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Platelet transfusion in a leukaemic child is usually given when the count falls below:', '["10 × 10⁹/L, or higher if bleeding", "100 × 10⁹/L, even if not bleeding", "150 × 10⁹/L in every child", "400 × 10⁹/L before any procedure"]'::jsonb, 0, 'Higher thresholds are used before procedures.', 'NNP 423 · Paediatric Nephrology'),
(2, 56, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Ureters grow into the kidneys and branch out into urine-collecting tubules normally.', '["pulmonary hypoplasia", "horse shoe kidney", "Dysplastic kidney", "renal cyst"]'::jsonb, 2, 'The correct answer is: Dysplastic kidney.', 'NNP 423 · Paediatric Nephrology'),
(2, 57, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Oxygen saturation of 95-100% in room air Conscious and easily arausable good muscle tone, respiration 30-60 is average 40 describes', '["A healthy baby", "An asphyxiated baby", "A sick neonate", "An apnoeic baby"]'::jsonb, 0, 'Good saturation, alertness, tone, and normal respiratory rate describe a healthy newborn.', 'NNP 423 · Paediatric Nephrology'),
(2, 58, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Severe pneumonia in a child is suggested by:', '["A mild dry cough lasting for a few days", "A normal breathing rate for the child''s age", "A runny nose with sneezing and mild fever", "Chest indrawing, grunting or SpO₂ below 90%"]'::jsonb, 3, 'WHO danger signs also include inability to drink and convulsions.', 'NNP 423 · Paediatric Nephrology'),
(2, 59, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Using the Holliday-Segar method, what is the daily maintenance IV fluid requirement for a 22 kg child?', '["1540 mL/day", "1000 mL/day", "2200 mL/day", "1100 mL/day"]'::jsonb, 0, 'First 10 kg = 100 mL/kg = 1000 mL; next 10 kg = 50 mL/kg = 500 mL; remaining 2 kg = 20 mL/kg = 40 mL. Total = 1000 + 500 + 40 = 1540 mL/day.', 'NNP 423 · Paediatric Nephrology'),
(2, 60, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Hypospadias is a condition in which:', '["The urethral opening is on the underside of the penis", "The foreskin is too tight to be pulled back over the glans", "The urethral opening is on the upper side of the penis", "The testis is absent from the scrotum on one side"]'::jsonb, 0, 'Circumcision is avoided because the foreskin may be needed for repair.', 'NNP 423 · Paediatric Nephrology'),
(2, 61, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Malrotation with midgut volvulus in a neonate is suspected with:', '["Sudden bilious vomiting", "Constipation without vomiting", "Excess weight gain", "Projectile non-bilious vomiting"]'::jsonb, 0, 'It is a surgical emergency because the bowel may die.', 'NNP 423 · Paediatric Nephrology'),
(2, 62, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Reduction of intussusception in a stable child is usually first attempted by:', '["Oral laxatives", "Immediate open surgery in all cases", "Air or contrast enema under imaging", "Abdominal massage at home"]'::jsonb, 2, 'Surgery is needed if this fails or if peritonitis or perforation is present.', 'NNP 423 · Paediatric Nephrology'),
(2, 63, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Room air is used at the start of term newborn resuscitation because:', '["Excess oxygen may harm the newborn", "Oxygen is never needed in newborns", "It is cheaper than oxygen", "It increases the heart rate faster"]'::jsonb, 0, 'Oxygen is titrated to target pre-ductal SpO₂ on the right hand.', 'NNP 423 · Paediatric Nephrology'),
(2, 64, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A neonate with seizures should first have checked:', '["Hearing response to sound", "Visual response to light", "Hip stability on testing", "Blood glucose and calcium"]'::jsonb, 3, 'Hypoglycaemia and hypocalcaemia are common treatable causes.', 'NNP 423 · Paediatric Nephrology'),
(2, 65, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Neonatal jaundice is usually clinically visible when serum bilirubin exceeds:', '["5 mg/dL", "15 mg/dL", "50 mg/dL", "25 mg/dL"]'::jsonb, 0, 'Jaundice becomes visible in neonates at serum bilirubin above about 5 mg/dL (85 µmol/L).', 'NNP 423 · Paediatric Nephrology'),
(2, 66, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Which is part of pre-operative care for a child with Hirschsprung''s disease?', '["Giving bowel washouts/enemas", "Shaving the axillary hair", "Obtaining consent from the child himself", "CT scan"]'::jsonb, 0, 'Rectal washouts or enemas decompress the bowel before surgery in Hirschsprung''s disease.', 'NNP 423 · Paediatric Nephrology'),
(2, 67, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Neuroblastoma in children arises most commonly from the:', '["Liver", "Adrenal gland", "Bone marrow only", "Kidney"]'::jsonb, 1, 'Raised urine catecholamines help the diagnosis.', 'NNP 423 · Paediatric Nephrology'),
(2, 68, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Minimum urine output in an infant after surgery should be about:', '["0.1 mL/kg/hour", "10 mL/kg/hour", "5 mL/kg/hour as a minimum", "1–2 mL/kg/hour"]'::jsonb, 3, 'Adults need at least 0.5 mL/kg/hour.', 'NNP 423 · Paediatric Nephrology'),
(2, 69, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'Magnesium sulphate given before very preterm birth (under 32 weeks) protects the baby against:', '["Cerebral palsy", "Neonatal sepsis", "Neonatal jaundice", "Respiratory distress syndrome"]'::jsonb, 0, 'It is a neuroprotective agent.', 'NNP 423 · Paediatric Nephrology'),
(2, 70, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 423 · Paediatric Nephrology', 'A child with Ebola is not infectious:', '["After death", "Before symptoms begin", "During the vomiting phase", "When bleeding"]'::jsonb, 1, 'Bodies remain highly infectious.', 'NNP 423 · Paediatric Nephrology'),
(2, 71, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'A nurse initiates prompt treatment after a client develops symptoms of a stressor reaction, aiming to reduce the effects and strengthen internal lines of resistance. This corresponds to which Neuman prevention level?', '["Preventive maintenance", "Secondary prevention", "Primary prevention", "Tertiary prevention"]'::jsonb, 1, 'Secondary prevention focuses on treatment of symptoms after a stressor has invaded the system and produced a reaction, aiming to strengthen the internal lines of resistance and restore stability.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 72, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'A patient with kidney disease is being managed by a multidisciplinary team. Which member is most appropriate to lead discussions on lifestyle modifications?', '["Dialysis nurse", "Nephrologist", "Social worker", "Nutritionist"]'::jsonb, 3, 'The correct answer is: Nutritionist.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 73, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'The first component of a nursing diagnosis statement is the:', '["Etiology", "Signs and symptoms", "Problem", "Related factors"]'::jsonb, 2, 'A nursing diagnosis statement begins with the Problem (diagnostic label), then the Etiology and the Signs/Symptoms (PES).', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 74, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Assessing how a client copes with stress, what support systems are available, and the effectiveness of the client''s usual coping strategies falls under which Gordon pattern?', '["Health perception-health management pattern", "Role-relationship pattern", "Value-belief pattern", "Coping-stress tolerance pattern"]'::jsonb, 3, 'The coping-stress tolerance pattern examines the client''s general coping style, effectiveness of coping in terms of stress tolerance, and support systems available.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 75, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'A patient under general anaesthesia requires which of Orem''s nursing systems?', '["No nursing system", "Partly compensatory", "Wholly compensatory", "Supportive-educative"]'::jsonb, 2, 'The patient cannot perform any self-care, so the nurse acts fully for them.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 76, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'The correct order of the nursing process is:', '["Assessment, diagnosis, planning, implementation, evaluation", "Planning, assessment, implementation, diagnosis, evaluation", "Assessment, planning, diagnosis, evaluation, implementation", "Diagnosis, planning, assessment, evaluation, implementation"]'::jsonb, 0, 'ADPIE is cyclical: evaluation leads back to reassessment.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 77, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'A patient newly diagnosed with diabetes and chronic kidney disease expresses confusion about their dietary restrictions. What is the most effective teaching strategy the nurse should use?', '["Discuss dietary changes only during follow-up appointments", "Provide written material without discussion", "Use a teach-back method to confirm understanding", "Limit discussions to potassium restrictions only"]'::jsonb, 2, 'The correct answer is: Use a teach-back method to confirm understanding.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 78, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'One of these is NOT among the four causes of illness worldwide', '["Diarrhea disease", "Complication of pregnancy", "Injuries", "Malaria"]'::jsonb, 3, 'The correct answer is: Malaria.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 79, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'One of the following is NOT among the key risk factors for various disease', '["Tobacco use and alcohol consumption", "Malnutrition", "Poor sanitation and access to clean water", "Physical activity"]'::jsonb, 3, 'The correct answer is: Physical activity.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 80, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'If a goal states a patient will gain 2kg in 4 weeks, and the patient gains only 1kg, the goal is classified as:', '["Cannot be evaluated", "Partially Met", "Not Met", "Met"]'::jsonb, 1, 'Some progress was made toward the goal, but the full target wasn''t reached, which is exactly what ''partially met'' describes.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 81, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Benner''s ''From Novice to Expert'' model describes:', '["Phases of general anaesthesia", "Stages of clinical competence", "Stages of wound healing", "Stages of a surgical operation"]'::jsonb, 1, 'It is used for training and mentoring of theatre nurses.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 82, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Roy''s model describes two major internal control processes, or coping subsystems, that a person uses to adapt to stimuli. What are they?', '["The core structure and flexible line of defense", "The self-care agency and therapeutic self-care demand", "The regulator and cognator subsystems", "The wholly compensatory and partly compensatory subsystems"]'::jsonb, 2, 'Roy identifies the regulator subsystem, which responds automatically through neural, chemical, and endocrine processes, and the cognator subsystem, which responds through cognitive-emotive channels such as perception, learning, judgment, and emotion.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 83, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Involving patients in their care decisions is crucial. Which strategy best facilitates this involvement?', '["Conducting brief, impersonal consultations", "Offering personalized education and encouraging questions", "Focusing on clinical outcomes without discussing patient preferences", "Providing one-size-fits-all educational materials"]'::jsonb, 1, 'The correct answer is: Offering personalized education and encouraging questions.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 84, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'The primary purpose of the nursing care plan is to:', '["Replace the doctor''s management plan", "Satisfy the accreditation inspectors only", "Provide individualised, coordinated care", "Increase the hospital''s income from care"]'::jsonb, 2, 'Plans are revised as the patient''s condition changes.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 85, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Mr Zee says his heart pounds and he is short of breath on the stairs. The nurse then auscultates the heart and checks the pulse. The nurse is:', '["Processing data into information", "Validating data", "Organising data", "Collecting data"]'::jsonb, 1, 'Checking pulse and heart sounds to confirm a subjective complaint (palpitations, breathlessness) is validating data.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 86, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'One of these is NOT a Key determinant to health in relation to global health', '["The measurement of health status", "The global burden of disease", "The importance of culture to health", "Health audit"]'::jsonb, 3, 'The correct answer is: Health audit.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 87, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'At which step of the nursing process is the PES statement written?', '["Assessment", "Diagnosis", "Implementation", "Planning"]'::jsonb, 1, 'The PES format (Problem, Etiology, Signs/Symptoms) is used to write the nursing diagnosis.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 88, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Feedback shows that caring is a key element of practice. Which theorist best supports this concept?', '["Watson", "Rogers", "Erikson", "Maslow"]'::jsonb, 0, 'Jean Watson''s Theory of Human Caring makes caring central to nursing.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 89, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Assessment of a client''s sensory abilities (vision, hearing), pain perception, memory, and decision-making ability is categorized under which Gordon pattern?', '["Role-relationship pattern", "Self-perception-self-concept pattern", "Coping-stress tolerance pattern", "Cognitive-perceptual pattern"]'::jsonb, 3, 'The cognitive-perceptual pattern covers sensory and neurological function, including vision, hearing, pain perception, and cognitive abilities such as memory and decision-making.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 90, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'The Stetler model of EBP has how many steps', '["4", "3", "5", "6"]'::jsonb, 1, 'The correct answer is: 3.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 91, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Which of the following is included among Henderson''s 14 basic needs?', '["Progress through the regulator and cognator coping subsystems", "Achieve pandimensional integrality with the environment", "Maintain the normal line of defense against stressors", "Avoid dangers in the environment and avoid injuring others"]'::jsonb, 3, '''Avoid dangers in the environment and avoid injuring others'' is one of Henderson''s 14 components of basic nursing care, addressing safety needs.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 92, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'The self-care deficit theory was proposed by:', '["Imogene King", "Dorothea Orem", "Virginia Henderson", "Betty Neuman"]'::jsonb, 1, 'Dorothea Orem proposed the self-care deficit theory.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 93, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'The domain of palliative care is the following EXCEPT', '["Physical", "Financial", "Psycho somatic", "Psychological"]'::jsonb, 1, 'The correct answer is: Financial.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 94, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Henderson''s philosophy of nursing is most heavily influenced by which broader conceptual approach?', '["A purely biomedical, disease-focused model excluding psychosocial needs", "A strictly systems-based, energy-field approach", "A needs-based, holistic approach similar in spirit to Maslow''s hierarchy of needs", "A model centered exclusively on environmental sanitation"]'::jsonb, 2, 'Henderson''s 14 components reflect a holistic, needs-based approach to care that parallels the breadth of Maslow''s hierarchy, spanning physiological, safety, social, and self-actualizing needs.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 95, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Which activity best describes the evaluation phase?', '["Interpret data and identify client problems", "Reassess and compare outcomes with the set objectives", "Establish short- and long-term goals", "Carry out nursing procedures and document"]'::jsonb, 1, 'Evaluation means reassessing the patient and comparing outcomes against the set goals.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 96, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'According to Orem, the sum of self-care actions required at a specific time to meet an individual''s known self-care requisites using appropriate methods is called the:', '["Therapeutic self-care demand", "Adaptive coping mechanism", "Functional health pattern", "Normal line of defense"]'::jsonb, 0, 'The therapeutic self-care demand is the totality of self-care actions to be performed for a specified period in order to meet an individual''s self-care requisites using valid methods and related sets of operations.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 97, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'An ''open system,'' as used in systems theory and in nursing models such as Neuman''s and Roy''s, is best defined as one that:', '["Exists in complete isolation from all outside influences", "Cannot be influenced by external stressors", "Exchanges matter, energy, and information with its environment", "Has no boundary separating it from its environment"]'::jsonb, 2, 'An open system continuously exchanges matter, energy, and information across its boundary with the surrounding environment, allowing for growth, adaptation, and change — this is how the human being is conceptualized in most nursing systems models.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 98, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'The goal of self-management education for CKD patients is to:', '["Reduce the number of medications", "Improve patient adherence to treatment and lifestyle changes", "Avoid dialysis permanently", "Make patients less dependent on healthcare providers"]'::jsonb, 1, 'The correct answer is: Improve patient adherence to treatment and lifestyle changes.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 99, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'Roy''s adaptation model views the patient as:', '["A passive recipient of all care", "An adaptive system responding to stimuli", "A financial unit in the hospital", "A machine to be repaired by experts"]'::jsonb, 1, 'The four adaptive modes are physiological, self-concept, role function and interdependence.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(2, 100, 'Nephrology Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues', 'One of the stated advantages of the nursing process is that it:', '["Eliminates the need for reassessment", "Promotes decisions based on routine, unquestioned habits", "Promotes individualised care and evidence-based decisions", "Removes the need for documentation"]'::jsonb, 2, 'The structured, data-driven nature of the nursing process supports care tailored to the individual patient, avoiding purely routine-based decisions.', 'NNP 425 · Advanced Nursing Concepts & Contemporary Issues'),
(3, 1, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Buying a new ventilator for the ICU falls under the:', '["Capital budget", "Operating budget", "Petty cash budget", "Personnel budget"]'::jsonb, 0, 'Operating budgets cover recurring costs such as consumables and utilities.', 'NNP 424 · Principles of Teaching and Management'),
(3, 2, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'ICU organisation in the curriculum includes the role of the nurse in:', '["Unit organisation, staffing, equipment and quality", "Hospital finance, billing and insurance claims only", "Pharmacy dispensing and stock control only", "Surgery and anaesthesia in the main theatre only"]'::jsonb, 0, 'The ICU nurse manager coordinates people, resources and standards.', 'NNP 424 · Principles of Teaching and Management'),
(3, 3, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'A hospital has many unreported needle-stick injuries and incidents of workplace violence, with no reporting or compensation system for staff. The victims of maleficence here are the:', '["Employees", "Patients", "Communities", "Families"]'::jsonb, 0, 'Institutions owe their employees a safe workplace. Unreported needle-stick injuries and violence with no compensation harm the staff.', 'NNP 424 · Principles of Teaching and Management'),
(3, 4, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Post-intensive care syndrome-family (PICS-F) includes:', '["Improved family relationships in every case", "Infection transmitted to the family members", "Anxiety, depression and PTSD in relatives", "Financial benefit to the family after discharge"]'::jsonb, 2, 'Follow-up clinics and diaries may reduce it.', 'NNP 424 · Principles of Teaching and Management'),
(3, 5, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'A manager who encourages staff to report errors without fear of unfair punishment is promoting a:', '["Just culture", "Competitive culture", "Punitive culture", "Blame culture"]'::jsonb, 0, 'A just culture encourages open error reporting by focusing on system factors rather than unfair individual blame.', 'NNP 424 · Principles of Teaching and Management'),
(3, 6, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'It is a specially staffed and equipped area of a hospital that provides a level of care intermediate between intensive care and general ward care. The critical care nurse knows this is:', '["Post anaesthesia recovery unit", "Critical care unit", "High dependency unit", "General ward"]'::jsonb, 2, 'An intermediate level of care between ICU and general ward defines a High Dependency Unit.', 'NNP 424 · Principles of Teaching and Management'),
(3, 7, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'The legal term for a person who brings a negligence claim is:', '["Defendant", "Judge", "Plaintiff", "Witness"]'::jsonb, 2, 'The defendant is the person or institution sued.', 'NNP 424 · Principles of Teaching and Management'),
(3, 8, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Documentation of hourly neurological observations for a patient with a head injury is an example of which type of standard in the Donabedian model?', '["Input", "Process", "Outcome", "Structure"]'::jsonb, 1, 'Process standards concern the actual activities carried out during care delivery, such as performing and recording assessments.', 'NNP 424 · Principles of Teaching and Management'),
(3, 9, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Staff appraisal in ICU is mainly used to:', '["Review performance and plan development", "Replace formal training and education", "Punish staff for errors made in the year", "Reduce the salaries of underperforming staff"]'::jsonb, 0, 'Regular feedback improves practice.', 'NNP 424 · Principles of Teaching and Management'),
(3, 10, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'He was the first to systematically describe management behaviour and also pioneered the identification of the principles and skills that underlie effective management.', '["Gashinge et all.", "Henri Fayol", "Max waber", "F. Taylor"]'::jsonb, 1, 'Henri Fayol is credited as the pioneer of systematic management theory and principles.', 'NNP 424 · Principles of Teaching and Management'),
(3, 11, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Management by objectives involves:', '["Setting agreed goals with staff and measuring results", "Setting goals for staff without asking for their input", "Managing the unit without any written goals at all", "Punishing staff who fail to meet the manager''s goals"]'::jsonb, 0, 'It increases motivation and clarity.', 'NNP 424 · Principles of Teaching and Management'),
(3, 12, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Which ethical principle refers to a patient''s right to make their own healthcare decisions?', '["Beneficence", "Justice", "Non-maleficence", "Autonomy"]'::jsonb, 3, 'Autonomy is the ethical principle recognising a competent patient''s right to self-determination in healthcare decisions.', 'NNP 424 · Principles of Teaching and Management'),
(3, 13, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Which among the following is not a concept of management?', '["Management by Systems", "management by culture", "Management by Results", "Management by Communication"]'::jsonb, 1, 'The correct answer is: management by culture.', 'NNP 424 · Principles of Teaching and Management'),
(3, 14, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Risk/Benefit Ratio is a consideration under which ethical principle?', '["Confidentiality", "Plagiarism avoidance", "Beneficence", "Justice"]'::jsonb, 2, 'Beneficence requires weighing potential harm against potential benefit before proceeding with research.', 'NNP 424 · Principles of Teaching and Management'),
(3, 15, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Interdepartmental communication between ICU and laboratory improves:', '["The spread of rumours among the staff", "The length of the family visiting hours", "The quality of catering for the patients", "Speed and accuracy of critical results"]'::jsonb, 3, 'Critical results are phoned and documented with read-back.', 'NNP 424 · Principles of Teaching and Management'),
(3, 16, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'The purchase of a new ventilator should be included in the:', '["Salary budget", "Revenue budget", "Operating budget", "Capital budget"]'::jsonb, 3, 'Major equipment purchases like a ventilator are capital expenditures, funded through the capital budget.', 'NNP 424 · Principles of Teaching and Management'),
(3, 17, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'The Critical Care Nurse manager knowns that, the art of getting an organizational activities done through other people using available resources is called.', '["Governance", "Delegation", "Leadership", "Management"]'::jsonb, 3, 'Achieving organisational goals through others using available resources is the definition of management.', 'NNP 424 · Principles of Teaching and Management'),
(3, 18, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'A staff nurse consistently exceeds performance expectations. The BEST management response is to:', '["Increase criticism", "Ignore the performance", "Assign all difficult patients to the nurse", "Recognize and reward excellent performance"]'::jsonb, 3, 'Recognising and rewarding strong performance reinforces and sustains it.', 'NNP 424 · Principles of Teaching and Management'),
(3, 19, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Felony-related cases in ICU (e.g. gunshot wounds) require the nurse to:', '["Refuse to treat the patient until police arrive", "Discharge the patient quickly to avoid trouble", "Give care and notify police as the law requires", "Investigate the crime personally at the bedside"]'::jsonb, 2, 'Treatment comes first; evidence is handled properly.', 'NNP 424 · Principles of Teaching and Management'),
(3, 20, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'The nurse manager wants to assess the compliance of staff with a new hand hygiene protocol. Which type of audit would be most effective for this purpose?', '["Retrospective audit", "Outcome audit", "Chart audit", "Concurrent audit"]'::jsonb, 3, 'A concurrent audit would be the most effective as it would allow the manager to observe the nurses'' hand hygiene practices in real-time, providing immediate feedback and a direct measure of compliance with the new protocol.', 'NNP 424 · Principles of Teaching and Management'),
(3, 21, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Passive euthanasia is sometimes confused with:', '["Starting CPR in an unexpected cardiac arrest", "Withdrawing or withholding futile treatment", "Giving adequate pain relief at the end of life", "Feeding the patient by nasogastric tube"]'::jsonb, 1, 'Withdrawing futile treatment is lawful when properly decided; actively killing is not.', 'NNP 424 · Principles of Teaching and Management'),
(3, 22, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Discharging patients from ICU at night is discouraged mainly because it is linked to:', '["Lower overall hospital costs", "A lower nursing workload overnight", "Better sleep for the patient", "Higher readmission and mortality"]'::jsonb, 3, 'Plan discharges in the daytime with a full handover to the ward.', 'NNP 424 · Principles of Teaching and Management'),
(3, 23, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Controlling concept include the following except', '["ruling control", "Feedback Control", "Feed Forward Control", "Concurrent Control"]'::jsonb, 0, 'The correct answer is: ruling control.', 'NNP 424 · Principles of Teaching and Management'),
(3, 24, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'Which of the following organizations requires a mechanism for addressing ethical issues?', '["The Joint Commission", "Society of Critical Care Medicine", "American Association of Critical-Care Nurses", "American Hospital Association"]'::jsonb, 0, 'The Joint Commission requires healthcare organisations to have a mechanism for addressing ethical issues.', 'NNP 424 · Principles of Teaching and Management'),
(3, 25, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'In a critical care unit, an audit reveals that pain assessment scores were documented for only 40% of eligible patients over the audit period, against a set standard of 100%. This finding represents:', '["A satisfactory outcome", "A structure standard being met", "A process criterion deficiency", "An incident report"]'::jsonb, 2, 'Failure to consistently perform and document a required nursing activity, such as pain assessment, reflects a process-level deficiency.', 'NNP 424 · Principles of Teaching and Management'),
(3, 26, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'The WHO surgical safety checklist has three phases:', '["Admission, surgery and discharge", "Before, during and after anaesthesia only", "Morning, afternoon and night", "Sign in, time out and sign out"]'::jsonb, 3, 'It reduces complications and mortality.', 'NNP 424 · Principles of Teaching and Management'),
(3, 27, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'A wife shouts at the ICU nurse that her husband is ''not being cared for''. This is most likely:', '["A clear sign that she intends to sue the hospital", "An expression of fear and helplessness under stress", "Evidence of a mental illness needing a psychiatrist", "Normal behaviour that needs no response from staff"]'::jsonb, 1, 'Acknowledge her feelings, listen and provide information calmly.', 'NNP 424 · Principles of Teaching and Management'),
(3, 28, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'When a patient wants to leave ICU against medical advice, the nurse should:', '["Explain the risks, inform the doctor, document", "Lock the doors so that the patient cannot leave", "Sedate the patient to keep them in the unit", "Ignore the request and continue the care"]'::jsonb, 0, 'A competent patient can refuse treatment.', 'NNP 424 · Principles of Teaching and Management'),
(3, 29, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'The recommended nurse-to-patient ratio for a ventilated Level 3 patient is:', '["1:1", "1:4", "1:6", "1:2"]'::jsonb, 0, 'Level 2 patients usually need 1:2 nursing.', 'NNP 424 · Principles of Teaching and Management'),
(3, 30, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'NNP 424 · Principles of Teaching and Management', 'In functional nursing, care is organized according to:', '["Patient diagnosis", "Bed numbers", "Nursing tasks", "Family preference"]'::jsonb, 2, 'Functional nursing organises care delivery around specific tasks rather than the whole patient.', 'NNP 424 · Principles of Teaching and Management'),
(3, 31, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'There is surgical emphysema. This is?', '["Pneumothorax", "Haemothorax", "Pleural effusion", "Haemopneumothorax"]'::jsonb, 0, 'Surgical (subcutaneous) emphysema is associated with air leakage, as in pneumothorax.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 32, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Systemic vascular resistance is high in:', '["Cardiogenic and hypovolaemic shock", "Early (warm) septic shock", "Anaphylactic shock after a drug", "Neurogenic shock after cord injury"]'::jsonb, 0, 'Distributive shock has low SVR.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 33, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'What is the normal finding in the water-seal chamber of a UWSD system for a patient with a resolved pneumothorax?', '["Continuous tidaling with no bubbling", "No bubbling and no tidaling", "Intermittent bubbling", "Continuous bubbling"]'::jsonb, 1, 'When a pneumothorax has resolved, there should be no more air leaking from the lung. Therefore, there should be no bubbling in the water-seal chamber. The absence of tidaling indicates that the lung is fully re-expanded and no longer has negative pressure on it.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 34, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Mr kifakat is on mechanical ventilator in ICU with a diagnosis of Brain death, what is his GCS', '["3/15", "6/15", "4/15", "5/15"]'::jsonb, 0, 'Brain death corresponds to the lowest possible GCS score of 3/15.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 35, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'IV furosemide is administered for acute pulmonary oedema. Besides diuresis, what additional early therapeutic effect makes it useful in this emergency?', '["Bronchodilation", "Positive inotropy", "Venodilation reducing preload", "Afterload reduction via arterial vasodilation"]'::jsonb, 2, 'Furosemide causes venodilation within minutes, before diuresis begins, which reduces preload and pulmonary venous congestion.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 36, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following is an indication of IABP:', '["Lower extremity ischemia", "Dissecting Aortic Aneurysm", "Cardiogenic shock", "Severe aortic Regurgitation"]'::jsonb, 2, 'Cardiogenic shock is a classic, well-established indication for IABP support.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 37, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'HFCC (High-Frequency Chest Wall Oscillation) uses an air-filled vest that squeezes the chest at a rate of:', '["50–60 times/second", "Once per minute", "5–20 times/second", "1–2 times/second"]'::jsonb, 2, 'This relatively fast oscillation rate helps loosen and move secretions toward the central airways.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 38, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Compartment syndrome following an electrical burn is treated with:', '["Fasciotomy", "Amputation immediately", "Compression bandaging", "Ice packs only"]'::jsonb, 0, 'Cutting open the tight fascia (fasciotomy) relieves the dangerous pressure building up inside the swollen muscle compartment.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 39, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Propranolol prophylaxis for variceal bleeding aims to reduce heart rate by approximately:', '["10% or to 90bpm", "No specific target", "25% or to 55bpm", "50% or to 40bpm"]'::jsonb, 2, 'This specific target reflects an adequate reduction in portal pressure achieved through beta-blockade.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 40, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following causes an EXUDATIVE pleural effusion?', '["Meigs'' syndrome", "Pulmonary tuberculosis", "Constrictive pericarditis", "Nephrotic syndrome"]'::jsonb, 1, 'TB, pneumonia, malignancy and PE cause exudates. Nephrotic syndrome, constrictive pericarditis and Meigs'' syndrome classically cause transudates.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 41, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following is a priority goal for the client with COPD?', '["Treating infectious agents.", "Increasing carbon dioxide levels in the blood.", "Minimizing chest pain.", "Maintaining functional ability."]'::jsonb, 3, 'Maintaining functional ability is a central, realistic priority goal in chronic COPD management.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 42, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A nurse is assessing a patient with a known history of COPD. The nurse should be aware that the patient is at risk for Type II respiratory failure due to:', '["A decrease in lung compliance", "Chronic carbon dioxide retention", "An increase in gas exchange efficiency", "A hyperactive respiratory drive"]'::jsonb, 1, 'Many patients with COPD have chronically elevated PaCO₂ levels, making them susceptible to Type II respiratory failure. Their respiratory system has become less responsive to high CO₂ levels, and a further increase can lead to hypoventilation and acidosis.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 43, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'As a nurse performing cardio-pulmonary resuscitation on a cardiac arrest patient, you are aware that the correct cardiac compression to optimised cardiac function is:', '["100 Compressions per minute", "115 compressions per minute", "120 Compressions per minute", "110 compressions per minute"]'::jsonb, 2, 'The recommended compression rate is about 120 compressions per minute (within the 100-120 range, closest to the given option).', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 44, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following is not a way to improve oxygenation?', '["Inspiratory time", "Respiratory rate", "FiO2", "PEEP"]'::jsonb, 1, 'Respiratory rate primarily affects ventilation/CO2 clearance, not oxygenation directly.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 45, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Immediate hemostatic responds to the damage vessel is', '["Platelet viscous metamorphosis", "Vasoconstriction", "Platelet aggregation", "Platelet adhesion"]'::jsonb, 1, 'Vasoconstriction is the very first immediate vascular response to vessel injury.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 46, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The presence of dysphagia suggests damage to cranial nerves:', '["III-VI", "IX-X", "V-VII", "VII-XI"]'::jsonb, 1, 'The glossopharyngeal (IX) and vagus (X) nerves supply the pharynx and larynx, so damage causes dysphagia.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 47, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'What is the primary cause of septic shock?', '["Poison", "Bleeding", "Infection(Blood)", "Medication allergy"]'::jsonb, 2, 'Septic shock is driven by infection (usually bloodstream).', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 48, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Inotropes increase:', '["Heart block", "Myocardial contractility", "Systemic vascular resistance only", "Venous capacity"]'::jsonb, 1, 'Examples: dobutamine, milrinone, adrenaline.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 49, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'An antiseptic differs from a disinfectant because an antiseptic is:', '["Always a sterilant that kills spores on instruments", "Used only on floors", "Stronger than all disinfectants", "Used on living tissue such as skin"]'::jsonb, 3, 'Disinfectants are for inanimate objects.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 50, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Active cycle of breathing technique ACBT is carried out in....', '["2 phase", "3 phases", "4 phases", "5 phases"]'::jsonb, 1, 'ACBT is carried out in 3 phases (breathing control, thoracic expansion, forced expiration).', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 51, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A 23 year old young adult presented to ER Road Traffic accident (RTA).He has poly traumas and massive bleeding. The characteristic of the blood is dark red in color and steady in flow. Which type of hemorrhage is this?', '["External Hemorrhage", "Arterial Hemorrhage", "Venous Hemorrhage", "Internal Hemorrhage"]'::jsonb, 2, 'Dark red, steady-flowing blood (not bright red and spurting) indicates venous bleeding.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 52, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The serum creatine kinase (CK) rises in a patient with myocardial infarction with in the first:', '["2-4 days", "12-18 hours", "4-6 hours", "3-6 days"]'::jsonb, 2, 'CK begins rising within about 4-6 hours of MI onset.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 53, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Symptoms associated with anaemia include', '["Decreased breathlessness", "Increased activity intolerance", "Moderate breathlessness", "Increased breathlessness"]'::jsonb, 3, 'Anaemia classically causes increased breathlessness due to reduced oxygen-carrying capacity.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 54, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Effective disaster response coordination between a hospital and emergency medical services primarily requires:', '["Only the hospital''s decisions being followed, regardless of on-scene conditions", "No advance planning, since disasters are unpredictable", "Each agency working entirely independently with no communication", "Clear communication, pre-established protocols, and a defined command structure"]'::jsonb, 3, 'Effective coordination relies on clear communication channels, pre-established protocols, and an agreed incident command structure established well before any disaster occurs.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 55, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A patient with a spinal cord injury above T6 develops sudden severe hypertension, a pounding headache, bradycardia, and flushing above the level of injury after the bladder becomes distended. Which NANDA-I diagnosis best matches this presentation?', '["Risk for Autonomic Dysreflexia", "Ineffective Cerebral Tissue Perfusion", "Autonomic Dysreflexia", "Decreased Cardiac Output"]'::jsonb, 2, 'Autonomic Dysreflexia (the actual diagnosis, since symptoms are already present) is triggered by a noxious stimulus such as bladder distension in patients with spinal cord injury at or above T6, producing paroxysmal hypertension, bradycardia, headache, and flushing.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 56, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which does NOT need to be excluded before testing for brain death?', '["Limb fractures", "Electrolyte imbalances", "Drug intoxication", "Hypothermia"]'::jsonb, 0, 'Before brainstem testing, exclude reversible causes: drugs and sedatives, hypothermia, and metabolic or electrolyte disturbances. Fractures do not affect the tests.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 57, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The correct order for donning personal protective equipment before entering an isolation room is:', '["Gloves, mask, gown, hand hygiene", "Mask, gloves, gown, hand hygiene", "Goggles, gown, hand hygiene, gloves, mask", "Hand hygiene, gown, mask, goggles, gloves"]'::jsonb, 3, 'Standard donning sequence is hand hygiene first, then gown, mask, goggles/eye protection, and gloves last, ensuring the most contamination-prone items (gloves) go on last.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 58, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'One of these is not a clinical presentation of asthma', '["upper limb vein distension", "Productive cough with thick sputum.", "Dyspnoea with prolonged expiratory phase", "Wheezing"]'::jsonb, 0, 'Upper limb vein distension is not a recognised feature of asthma.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 59, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A patient in the ICU develops new-onset agitation, disorientation, and pulling at lines, fluctuating throughout the day. The nurse should assess for:', '["Normal ICU behaviour requiring no assessment", "Definite dementia with no other cause considered", "Nothing — this is expected and not clinically significant", "ICU delirium, using a validated delirium assessment tool"]'::jsonb, 3, 'Fluctuating attention/cognition disturbance in the ICU should prompt formal delirium screening (e.g. CAM-ICU), since delirium is common, often reversible, but frequently under-recognised (especially the hypoactive form).', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 60, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Rapid deflation of Balloon of IABP will decrease:', '["After Load", "Contraction", "Pre-load", "Heart Rate"]'::jsonb, 0, 'Rapid deflation just before systole reduces the resistance (afterload) the heart must pump against.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 61, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The layer of skin containing blood vessels, nerves and sweat glands is the:', '["Epidermis", "Hypodermis only", "Dermis", "Stratum corneum"]'::jsonb, 2, 'The epidermis is avascular.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 62, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Peripheral polyneuritis causing glove-and-stocking sensory loss is commonly due to:', '["Diabetes and vitamin B deficiency", "Excess intake of vitamin C", "Hypertension and bronchial asthma", "Hypothyroidism on its own"]'::jsonb, 0, 'Alcohol and drugs (e.g. isoniazid without pyridoxine) are other causes.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 63, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Ventilator circuits should be changed:', '["Before every suction, to keep them clean", "Every day at midnight, whatever their state", "Every 6 hours routinely, by the night nurse", "Only when visibly soiled or malfunctioning"]'::jsonb, 3, 'Frequent circuit changes increase VAP risk.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 64, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following factors can cause hepatitis A', '["Eating contaminated food", "Blood transfusions with infected blood.", "Sexual contact with an infected person.", "Contact with infected blood."]'::jsonb, 0, 'Hepatitis A spreads via the faecal-oral route, commonly through contaminated food.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 65, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A heart rate below what value is used as an ICU admission threshold?', '["<90bpm", "<40bpm", "<70bpm", "<55bpm"]'::jsonb, 3, 'A heart rate this slow may signal a dangerous underlying problem needing closer monitoring.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 66, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'What is the appropriate amount of time to suction a patient in a single interval?', '["No more than 10 – 20 seconds", "No more than 10 – 15 seconds", "No more than 5 – 10 seconds", "No more than 20 – 30 seconds"]'::jsonb, 1, 'Apply suction for no more than 10–15 seconds per pass to limit hypoxaemia, bradycardia and mucosal trauma. Pre-oxygenate first.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 67, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'What is the generally recommended target cerebral perfusion pressure (CPP) in the management of severe traumatic brain injury?', '["90-100 mmHg", "60-70 mmHg", "Greater than 100 mmHg", "40-50 mmHg"]'::jsonb, 1, 'Current guidelines recommend maintaining CPP in the range of 60-70 mmHg to ensure adequate cerebral perfusion while avoiding the complications of excessive fluid and vasopressor use.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 68, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A sudden fall in SpO₂ with absent breath sounds on the left after intubation suggests:', '["A massive pulmonary embolism", "Right main bronchus intubation", "Severe bronchospasm on both sides", "A left-sided pneumothorax in every case"]'::jsonb, 1, 'Withdraw the tube a few centimetres and recheck.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 69, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'About cardiac pacemaker', '["The right internal jugular and the left subclavian veins are often preferred", "Cardiac pacemakers can be inserted by trans venous only", "Most often the trans venous approach is used", "When viewed on a chest radiograph, the pacemaker lead should terminate in the right ventricular apex"]'::jsonb, 1, 'Pacemakers can also be inserted via epicardial/surgical approaches, not only transvenously — making that absolute statement incorrect.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 70, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which of the following is the most widely used method of gut decontamination in modern poisoning management, when indicated?', '["Single-dose activated charcoal", "Whole bowel irrigation for all ingestions", "Gastric lavage as routine for all poisonings", "Induced vomiting with ipecac"]'::jsonb, 0, 'Single-dose activated charcoal, given early after ingestion of an appropriate toxin, is the most commonly used and best-evidenced gut decontamination method in current poisoning management.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 71, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which ventilator practice should be avoided in a hemodynamically unstable patient with status asthmaticus, due to risk of breath stacking?', '["A permissive hypercapnia strategy", "High respiratory rates with short expiratory time", "Low tidal volume ventilation", "Adequate sedation to reduce patient-ventilator dyssynchrony"]'::jsonb, 1, 'Rapid respiratory rates shorten expiratory time, which in severe bronchospasm causes incomplete exhalation, air trapping, auto-PEEP, and risk of barotrauma or hemodynamic collapse.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 72, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Hypothermia in trauma (accidental hypothermia) is considered severe below:', '["32 °C", "28 °C", "35 °C", "34 °C"]'::jsonb, 1, 'Severe hypothermia risks VF; patients should be handled gently and rewarmed actively.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 73, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A client is scheduled for a cardiac catheterization using a radiopaque dye. Which of the following assessments is most critical before the procedure?', '["Baseline peripheral pulse rates", "Intake and output", "Allergy to iodine or shellfish", "Height and weight"]'::jsonb, 2, 'Checking for iodine/shellfish allergy is critical before administering iodine-based radiopaque contrast.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 74, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'You have been instructed to deliver a health talk to a group of hypertensive patient on weight control; what will be your time estimation?', '["About 2 hour", "About 20 minute", "About 30 minute", "About 1 hour"]'::jsonb, 1, 'A health talk on a focused topic like weight control is typically estimated at about 20 minutes.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 75, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Tidal volume 500 mL, plateau pressure 30 cmH₂O and PEEP 10 cmH₂O give a static compliance of:', '["12.5 mL/cmH₂O", "50 mL/cmH₂O", "16.7 mL/cmH₂O", "25 mL/cmH₂O"]'::jsonb, 3, 'Static compliance = VT ÷ (plateau − PEEP) = 500 ÷ 20. Normal is about 50–100 mL/cmH₂O.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 76, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A 7-year-old client is brought to the E.R. He’s tachypneic and afebrile and has a respiratory rate of 36 breaths/minute and a nonproductive cough. He recently had a cold. From his history, the client may have which of the following?', '["Chronic obstructive pulmonary disease (COPD)", "Emphysema", "Acute asthma", "Bronchial pneumonia"]'::jsonb, 2, 'A tachypnoeic, afebrile child with a dry cough after a recent cold fits acute asthma.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 77, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A nurse is preparing for the admission of a client with heart failure who is being sent directly to the hospital from the physician''s office. The nurse would plan on having which of the following medication readily available for use?', '["metoprolol (Lopressor)", "propranolol (Inderal)", "diltiazem (Cardizem)", "digoxin (Lanoxin)"]'::jsonb, 3, 'Digoxin is a standard medication kept ready for heart failure management.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 78, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A nurse is teaching a family about the classification of burns. A third-degree burn is also known as a:', '["Superficial partial-thickness burn", "Superficial burn", "Partial-thickness burn", "Full-thickness burn"]'::jsonb, 3, 'A third-degree burn is a full-thickness burn, meaning it extends through all layers of the skin, destroying the epidermis, dermis, and often the underlying fat, muscle, and bone.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 79, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A sickle cell disease patient presented with chest pain, low Spo2, cough, dyspnea, which of these is the cause?', '["Acute Chest Syndrome", "Acute Anaemia", "Vaso-Occlusive Crisis", "Acute Asthmatic"]'::jsonb, 0, 'Chest pain, low SpO2, cough, and dyspnoea in sickle cell disease describe acute chest syndrome.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 80, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', '## CCNP EXAM - PAPER II.docx Histamine, a mediator that supports the inflammatory process in asthma is secreted by:', '["Lymphocytes", "Mast cells", "Eosinophils", "Neutrophils"]'::jsonb, 1, 'Mast cells release histamine as part of the allergic/inflammatory response in asthma.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 81, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A patient with fulminant hepatic failure develops worsening confusion and asterixis (flapping tremor). This presentation is most consistent with:', '["A normal finding with no significance", "Hypoglycaemia unrelated to liver disease", "Simple fatigue", "Hepatic encephalopathy"]'::jsonb, 3, 'Confusion with asterixis in a patient with liver failure is characteristic of hepatic encephalopathy, related to the liver''s reduced ability to clear ammonia.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 82, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A high white cell count with many neutrophils most often suggests:', '["Anaemia", "Bacterial infection", "Viral infection always", "Allergy only"]'::jsonb, 1, 'Lymphocytes rise more in viral infections.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 83, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'According to 2017 ACC/AHA criteria, Stage II hypertension is defined as:', '["<120/<80", "130–139/80–89", "≥140/≥90", "120–129/<80"]'::jsonb, 2, 'This is the highest defined category, indicating significant hypertension requiring active management.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 84, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Volume of air inspired or expired by a person from lungs in a minute:', '["Expiratory Volume", "Inspiratory Volume", "Tidal Volume", "Minute Volume"]'::jsonb, 3, 'Total air moved per minute is minute volume (tidal volume × respiratory rate).', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 85, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which symptom is most likely in a client with mitral regurgitation?', '["Chest pain", "Increased creatine kinase", "Exertional dyspnoea", "Altered level of consciousness"]'::jsonb, 2, 'Mitral regurgitation backs blood up into the left atrium and pulmonary veins, causing exertional dyspnoea, fatigue and palpitations.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 86, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'One of the tools used for monitoring a polytrauma patient is Glasgow Coma scale. The second parameter has a total of what score?', '["15", "5", "6", "3"]'::jsonb, 2, 'The GCS verbal response component has a maximum score of 5, but ''second parameter'' referring to eye opening or a specific listed subscale... commonly the verbal component max is 5; select based on standard subscale totals.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 87, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'On taking over in ICU from afternoon nurses, you discovered that a bottle of drug was not labelled and no information from handing over Nurse, what is the possible cause of this lapse?', '["Poor communication", "The patient relatives did not communicate to the Nurses", "Lack of labeling from the pharmacy that dispense the drugs", "Improper handing and taking over from previous shift"]'::jsonb, 3, 'Improper handover between shifts is the most likely cause of missing drug labelling/information.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 88, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which mode of mechanical ventilation delivers a preset volume/pressure with every breath, whether patient-triggered or machine-triggered, providing full support?', '["Assist-Control (AC)", "Pressure Support Ventilation alone at low levels", "T-piece trial", "CPAP with no additional support"]'::jsonb, 0, 'Assist-Control ventilation delivers a full preset breath for every triggered or mandatory breath, providing complete ventilatory support.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 89, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'A condition characterised by a prolonged PR interval more than 0.2 secs in ECG is called:', '["Complete block", "Mobiz Type II AV block", "Second degree AV block", "First degree Av block"]'::jsonb, 3, 'PR interval >0.2 sec with every beat still conducting = first-degree AV block.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 90, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Goal for a child with respiratory infection:  "The child will exhibit adequate oxygenation and ___ airway.  Keep O2 saturation >92-93%.', '["Patent", "Pertinent", "Cleared", "Potent"]'::jsonb, 0, 'The goal wording specifically calls for a patent (open, clear) airway.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 91, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Which one of the following test is used to monitor a Diabetes Mellitus patient?', '["Total protein", "Alkaline phosphatase", "Fasting Blood Sugar", "Creatinine test"]'::jsonb, 2, 'Fasting blood sugar is the standard test used to monitor diabetes control.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 92, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'In patients with normal cardiopulmonary status, increasing the ________ is the treatment of choice in improving the patient''s oxygenation.', '["PEEP", "VT", "PSV", "FiO2"]'::jsonb, 3, 'Increasing FiO2 is the first-line way to improve oxygenation in a patient with otherwise normal cardiopulmonary status.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 93, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Muscle wasting (hypotrophy) usually develops with disease of the:', '["Lower motor neuron", "Caudate nucleus", "Cerebellum", "Upper motor neuron"]'::jsonb, 0, 'Marked muscle wasting is a lower motor neuron sign, caused by loss of the trophic nerve supply to the muscle.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 94, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The most resistant form of microbial life to heat and chemicals, apart from prions, is:', '["Enveloped viruses", "Vegetative Gram-positive bacteria", "Bacterial spores", "Fungal yeasts"]'::jsonb, 2, 'Spores (Clostridium, Bacillus) have thick protective coats and survive boiling and many disinfectants. Enveloped viruses (HIV, hepatitis B) are the most easily destroyed.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 95, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'The critical care nurse knows the term to describe accumulation of air within pleural space is called...', '["Haemothorax", "Pneumothorax", "Pneumohemothorax", "Tension pneumothorax"]'::jsonb, 1, 'Air accumulation in the pleural space is simply termed pneumothorax.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 96, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'When hypocalcaemia occurs, the nurse avoids disturbing the client because:', '["Movement increases bleeding", "Pain relief is priority", "Rest prevents infection", "Anxiety worsens spasms"]'::jsonb, 3, 'Reducing stimulation avoids triggering worse spasms while calcium levels are corrected.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 97, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Babinski''s sign, when positive (upgoing toe) in an adult, suggests:', '["Upper motor neuron pathology", "A peripheral nerve injury only", "No clinical significance", "A normal finding in all healthy adults"]'::jsonb, 0, 'A positive Babinski sign (extension of the big toe) in an adult indicates upper motor neuron dysfunction; it is a normal finding only in infants under about 2 years.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 98, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'Immediately after a burn injury, there is release of ........?', '["Thromboxane A2", "Histamine", "Catecholamines", "Oxygen radicals"]'::jsonb, 2, 'Catecholamines are released immediately as part of the stress/hypermetabolic response to a burn injury.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 99, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'This occurs when air enters the pleura but cannot escape, resulting in one-way valve effect, thus produces shift in the mediastinum.', '["Traumatic pneumothorax", "Tension pneumothorax", "Primary spontaneous pneumothorax", "Secondary spontaneous pneumothorax"]'::jsonb, 1, 'A one-way air-trapping valve effect with mediastinal shift is the hallmark of tension pneumothorax.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)'),
(3, 100, 'Nephrology Nursing Mock — Day 6 Night (Nov 2026)', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)', 'While performing hemodynamic monitoring of the patient, the transducer should be kept at the Phlebostatic axis. The nurse knows that it is located at:', '["Intersection of line between 3rd intercostal space and mid-axillary line", "Intersection of line between 4th intercostal space and mid-axillary line", "Intersection of line between 5th intercostal space and mid-axillary line", "Intersection of line between 2nd intercostal space and mid-axillary line"]'::jsonb, 1, 'The phlebostatic axis sits at the 4th intercostal space, mid-axillary line.', 'Comprehensive Revision (Critical Care, Emergencies & Infection Control)');
